import {getPrivateState,getPrivateStatus,refreshPrivate,unlockPrivate,lockPrivate,renderPrivatePanel} from './private-ui.js';
import {DEFAULT_CONFIG,normalizeCandles,analyze,createAccount,markToMarket,openPaperTrade,closePaperTrade,processCandles,backtest,reviewStrategy,aggregateCandles,patternConfirmation,performanceStats,goalEstimate} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=2)=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:d,maximumFractionDigits:d}).format(n):'—';
const priceMoney=n=>money(n,n<1?4:n<10?3:2);
const percent=(n,d=2)=>Number.isFinite(n)?`${n>0?'+':''}${(n*100).toFixed(d)}%`:'—';
const date=t=>t?new Date(typeof t==='number'?t*1000:t).toLocaleString('en-GB',{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':'Not yet';
const tone=n=>n>0?'positive':n<0?'negative':'neutral';
const names={'BTC-USD':'Bitcoin','ETH-USD':'Ethereum','SOL-USD':'Solana','XRP-USD':'XRP','ADA-USD':'Cardano','DOGE-USD':'Dogecoin','LINK-USD':'Chainlink','AVAX-USD':'Avalanche'};
const symbols={'BTC-USD':'₿','ETH-USD':'Ξ','SOL-USD':'◎','XRP-USD':'✕','ADA-USD':'₳','DOGE-USD':'Ð','LINK-USD':'⬡','AVAX-USD':'△'};
const repo='https://github.com/akc302/paperTradeCodex';
let learning={status:'not-loaded'},operations={},evidence={},research={},team={},supervisor={};
let storageAvailable=true;
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{storageAvailable=false;return fallback}}
let personal=readLocal('level-lab-account-v1',createAccount());
let personalConfig=readLocal('level-lab-config-v1',{...DEFAULT_CONFIG});
let market={products:{}},paper={account:createAccount(),config:{...DEFAULT_CONFIG},products:['BTC-USD']},reviews={reviews:[]};
let selected='BTC-USD',accountMode='shared',chartHours=1,quotes={},loading=false,backtestResult=null,localReview=null,toastTimer;
const pages={overview:['Overview','Your edge starts here.','A clear view of your markets, your trades, and what comes next.'],journal:['Trade journal','Every trade tells a story.','Track your decisions, execution costs, and results in one place.'],strategy:['Strategy lab','Make your process measurable.','Test support and resistance ideas before you put them into practice.'],updates:['Daily reviews','A little more evidence. Every day.','Follow the scheduled strategy reviews and see exactly what changed.'],settings:['Settings','Set the rules of your lab.','Manage your practice account, risk preferences, and data.']};
const page=()=>Object.hasOwn(pages,location.hash.slice(1))?location.hash.slice(1):'overview';
const account=()=>accountMode==='private'?(getPrivateState()?.account??createAccount()):accountMode==='shared'?paper.account:personal;
const config=()=>accountMode==='private'?(getPrivateState()?.config??DEFAULT_CONFIG):accountMode==='shared'?paper.config:personalConfig;
const currentReviews=()=>{
 const state=accountMode==='private'?getPrivateState():null;
 const report=accountMode==='private'?state?.journalResearch:research;
 if(!report?.reviewDate)return accountMode==='private'?{reviews:state?.reviews??[]}:reviews;
 const history=accountMode==='private'?(state.journalResearchHistory??[report]):(research.history??[report]);
 return {reviews:history.flatMap(day=>(day.proposals??[]).map(p=>{
  const o=day.outcomes?.byMarket?.[p.product];
  return {...p,date:day.reviewDate,time:day.reviewedAt,status:p.status==='adopted-for-future-entries'?'promoted':p.status==='insufficient-executed-evidence'?'insufficient-data':'retained',outcomes:{closedTrades:o?.trades??0,pnl:o?.netPnl??0,fees:o?.grossFees??0}};
 }))};
};
const candles=(product=selected)=>normalizeCandles(market.products[product]?.candles??[]).filter(c=>c.time+3600<=Date.now()/1000);
const prices=()=>Object.fromEntries(Object.keys(names).map(p=>[p,freshQuote(p)?quotes[p].price:candles(p).at(-1)?.close]));
function persist(){try{localStorage.setItem('level-lab-account-v1',JSON.stringify(personal));localStorage.setItem('level-lab-config-v1',JSON.stringify(personalConfig))}catch{storageAvailable=false;notify('Browser storage is unavailable. Export your practice data before leaving.')}}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function analysis(){return analyze(candles(),config())}
function freshQuote(product=selected){const q=quotes[product];return !!q&&Date.now()-q.receivedAt<120000&&Date.now()-Date.parse(q.time)<120000}
function dataWarning(){const bars=candles(),last=bars.at(-1);const stale=!last||Date.now()/1000-(last.time+3600)>14400;const errors=market.errors??[];const messages=[];if(operations.scheduleEventCount===0)messages.push('GitHub timer has no verified scheduled runs. Live prices do not mean the unattended trader is running. Last server update: '+date(paper.updatedAt));if(operations.scheduleEventCount>0&&operations.tradingCadenceVerified!==true)messages.push('Some scheduled runs are verified, but regular two-hour delivery is not. Check server timestamps.');if(stale)messages.push('Market snapshot is stale. Check refresh or the scheduled workflow before relying on signals.');if(errors.length)messages.push(`${errors.length} scheduled market warning(s). See Daily reviews for details.`);if(accountMode==='shared'){const updated=Date.parse(paper.updatedAt??'');const cursor=paper.account?.lastProcessed?.['BTC-USD'];if(!Number.isFinite(updated)||Date.now()-updated>135*60000||!cursor||Date.now()/1000-(cursor+3600)>4*3600)messages.push(`Scheduled account is not current (last update: ${date(paper.updatedAt)}). Live browser quotes do not advance it; check GitHub Actions.`);}if(accountMode==='private'&&getPrivateState()){const privateTime=Date.parse(getPrivateState().updatedAt??'');if(!Number.isFinite(privateTime)||Date.now()-privateTime>135*60000)messages.push('Private paper-account state is stale. Check its encrypted update timestamp and scheduler key.');if(getPrivateStatus().automation!=='updated')messages.push('Private unattended updates are not active yet. Configure PAPER_STATE_KEY in GitHub Actions secrets.');}if(!storageAvailable)messages.push('Browser storage is unavailable. Practice changes may not survive closing this tab.');$('#notice').hidden=!messages.length;$('#notice').textContent=messages.join(' ')}

async function json(path){const r=await fetch(`${path}${path.includes('?')?'&':'?'}t=${Date.now()}`,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error(`Could not load ${path} (${r.status}).`);return r.json()}
async function loadSnapshots(){const results=await Promise.allSettled(['market','paper','reviews'].map(n=>json(`./data/${n}.json`)));if(results[0].status==='fulfilled')market=results[0].value;else {try{const seed=await json('./data/mcp-seed.json');market={updatedAt:seed.capturedAt,source:seed.source,granularity:3600,products:Object.fromEntries(Object.entries(seed.products).map(([p,v])=>[p,{candles:normalizeCandles(v),fetchedAt:seed.capturedAt,source:seed.source}]))};}catch{}}if(results[1].status==='fulfilled')paper=results[1].value;if(results[2].status==='fulfilled')reviews=results[2].value;try{learning=await json('./data/learning.json')??learning;operations=await json('./data/operations.json')??operations;evidence=await json('./data/evidence.json')??evidence;research=await json('./data/research.json')??research;}catch{}try{team=await json('./data/team-report.json')??team;}catch{}try{supervisor=await json('./data/supervisor-report.json')??supervisor;}catch{}await refreshPrivate(json);return results.some(r=>r.status==='fulfilled')}
async function refresh(silent=false){
  if(loading)return;loading=true;$('#refresh').classList.add('busy');
  try{
    await loadSnapshots();
    const outcomes=await Promise.allSettled(Object.keys(names).map(async (product,index)=>{
      if(index>0&&typeof window.requestAnimationFrame==='function')await new Promise(resolve=>setTimeout(resolve,index*180));
      const [bars,ticker]=await Promise.all([json(`https://api.exchange.coinbase.com/products/${product}/candles?granularity=3600`),json(`https://api.exchange.coinbase.com/products/${product}/ticker`)]);
      const merged=normalizeCandles([...(market.products[product]?.candles??[]),...normalizeCandles(bars)]).filter(c=>c.time+3600<=Date.now()/1000).slice(-2160);
      if(!merged.length||!Number.isFinite(+ticker.price)||+ticker.price<=0)throw new Error('Invalid market response');
      const quoteTime=Date.parse(ticker.time);if(!Number.isFinite(quoteTime)||Date.now()-quoteTime>120000||quoteTime-Date.now()>30000)throw new Error('Coinbase quote is stale.');
      market.products[product]={...market.products[product],candles:merged,browserFetchedAt:new Date().toISOString()};
      quotes[product]={price:+ticker.price,receivedAt:Date.now(),time:ticker.time};
      processCandles(personal,product,merged,personalConfig,{autoTrade:false});
      const position=personal.positions.find(p=>p.product===product);
      // Browser practice exits can also observe fresh quotes between hourly closes.
      if(position&&+ticker.price<=position.stop)closePaperTrade(personal,position.id,+ticker.price,Date.now()/1000,'stop (observed quote)',personalConfig);
      else if(position&&+ticker.price>=position.target)closePaperTrade(personal,position.id,position.target,Date.now()/1000,'target (observed quote)',personalConfig);
      personal.marks[product]=+ticker.price;
    }));
    const good=outcomes.filter(r=>r.status==='fulfilled').length;
    persist();if(!silent)notify(good?`${good} markets refreshed from Coinbase.`:'Live feed unavailable. Showing the last saved snapshot; new practice entries are paused.');
  }catch(error){if(!silent)notify(error.message)}finally{loading=false;$('#refresh').classList.remove('busy');render()}
}

function metric(label,value,sub,icon='◫'){return `<div class="metric"><div class="metric-head">${label}<span class="metric-icon" aria-hidden="true">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-sub">${sub}</div></div>`}
function metrics(){const a=account(),s=markToMarket(a,prices());return `<div class="metrics">${metric('Paper equity',money(s.equity),`<span class="${tone(s.equity-a.initial)}">${percent((s.equity-a.initial)/a.initial)}</span> <span>from ${money(a.initial,0)} virtual cash</span>`,'◈')}${metric('Realized P&L',`<span class="${tone(s.realized)}">${money(s.realized)}</span>`,`${a.trades.length} closed trades · after fees`,'⌁')}${metric('Win rate',a.trades.length?(s.winRate*100).toFixed(1)+'%':'—',a.trades.length?`${a.trades.filter(t=>t.pnl>0).length} winners / ${a.trades.length} closed trades`:'Waiting for the first closed trade','◎')}${metric('Available cash',money(a.cash),`${a.positions.length} open position${a.positions.length===1?'':'s'} · no leverage`,'▱')}</div>`}

function chart(){
  const bars=(chartHours===4?aggregateCandles(candles(),4):candles()).slice(-72),a=analysis(),W=Math.max(340,Math.min(820,$('.chart')?.clientWidth||((window.innerWidth??1200)-(window.innerWidth>980?600:window.innerWidth>740?400:window.innerWidth>480?140:50)))),H=280,left=12,right=79,top=18,bottom=29;
  if(!bars.length)return '<div class="loading">Waiting for Coinbase market data…</div>';
  const levels=[a.support,a.resistance].filter(Number.isFinite);let lo=Math.min(...bars.map(c=>c.low),...levels),hi=Math.max(...bars.map(c=>c.high),...levels);const pad=(hi-lo)*.12||hi*.01;lo-=pad;hi+=pad;
  const x=i=>left+i*(W-left-right)/Math.max(1,bars.length-1),y=p=>top+(hi-p)/(hi-lo)*(H-top-bottom),cw=Math.max(2,(W-left-right)/bars.length*.58);
  let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(selected)} ${chartHours}-hour candlestick chart with confirmed support and resistance"><defs><linearGradient id="chart-fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b9f47a" stop-opacity=".08"/><stop offset="1" stop-color="#b9f47a" stop-opacity="0"/></linearGradient></defs>`;
  for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,Y=y(v);svg+=`<line x1="${left}" y1="${Y}" x2="${W-right+10}" y2="${Y}" stroke="#2a342b" stroke-dasharray="3 5"/><text x="${W-right+17}" y="${Y+4}" fill="#7d8d80" font-size="10" font-family="monospace">${money(v,v<10?4:v<100?2:0)}</text>`}
  const path=bars.map((c,i)=>`${i?'L':'M'}${x(i)},${y(c.close)}`).join(' ');svg+=`<path d="${path} L${x(bars.length-1)},${H-bottom} L${left},${H-bottom}Z" fill="url(#chart-fade)"/>`;
  bars.forEach((c,i)=>{const color=c.close>=c.open?'#a9dc91':'#cb8174';svg+=`<g><title>${esc(date(c.time))} · O ${money(c.open)} · H ${money(c.high)} · L ${money(c.low)} · C ${money(c.close)}</title><line x1="${x(i)}" y1="${y(c.high)}" x2="${x(i)}" y2="${y(c.low)}" stroke="${color}"/><rect x="${x(i)-cw/2}" y="${y(Math.max(c.open,c.close))}" width="${cw}" height="${Math.max(1,Math.abs(y(c.open)-y(c.close)))}" fill="${color}" rx=".7"/></g>`});
  for(const [v,color,label] of [[a.support,'#b9f47a','SUPPORT'],[a.resistance,'#e6bb78','RESISTANCE']])if(v)svg+=`<line x1="${left}" y1="${y(v)}" x2="${W-right+9}" y2="${y(v)}" stroke="${color}" stroke-width="1.2" stroke-dasharray="6 5"/><rect x="${left+8}" y="${y(v)-18}" width="86" height="16" rx="3" fill="#1b2419"/><text x="${left+13}" y="${y(v)-7}" fill="${color}" font-size="8" font-family="sans-serif" letter-spacing="1">${label}</text>`;
  svg+=`<defs><clipPath id="trend-clip"><rect x="${left}" y="${top}" width="${W-left-right}" height="${H-top-bottom}"/></clipPath></defs>`;
  for(const line of a.trendlines??[]){const first=Math.max(bars[0].time,line.startTime),last=bars.at(-1).time;if(first>=last)continue;const px=t=>left+(t-bars[0].time)/(last-bars[0].time)*(W-left-right),py=t=>y(line.originPrice+line.slope*(t-line.originTime)/14400);svg+=`<path d="M${px(first)},${py(first)} L${px(last)},${py(last)}" clip-path="url(#trend-clip)" fill="none" stroke="${line.type==='support'?'#8fdbe8':'#b1a2ee'}" stroke-width="1.5" stroke-dasharray="8 3"><title>${esc(line.direction)} ${esc(line.type)} trendline · ${line.touches.length} confirmed touches</title></path>`;}
  const swings=[];let priorHigh=null,priorLow=null;
  for(let i=3;i<bars.length-3;i++){const around=bars.slice(i-3,i+4);if(around.every(b=>b.high<=bars[i].high)){swings.push({i,p:bars[i].high,label:priorHigh==null?'H':bars[i].high>priorHigh?'HH':'LH',above:true});priorHigh=bars[i].high;}if(around.every(b=>b.low>=bars[i].low)){swings.push({i,p:bars[i].low,label:priorLow==null?'L':bars[i].low>priorLow?'HL':'LL',above:false});priorLow=bars[i].low;}}
  for(const point of swings.slice(-8))svg+=`<text x="${x(point.i)}" y="${y(point.p)+(point.above?-8:14)}" fill="${point.above?'#ef8f87':'#b9f47a'}" font-size="10" text-anchor="middle">${point.label}</text>`;
  for(let i=0;i<4;i++){const index=Math.round(i*(bars.length-1)/3);svg+=`<text x="${x(index)}" y="${H-7}" text-anchor="${i===0?'start':i===3?'end':'middle'}" fill="#7d8d80" font-size="10">${esc(new Date(bars[index].time*1000).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',timeZone:'UTC'}))}</text>`}
  return svg+'</svg>';
}
function marketPanel(){const bars=candles(),a=analysis(),price=prices()[selected],ref=bars.at(-25)?.close,change=ref?(price-ref)/ref:NaN;return `<section class="panel"><div class="panel-head"><div><h2>${esc(names[selected])} <span class="muted small">/ USD</span></h2><p>Support & resistance · spot market</p><div class="range-tabs"><button data-hours="1" class="${chartHours===1?'positive':''}">1H</button><button data-hours="4" class="${chartHours===4?'positive':''}">4H</button></div></div><div class="market-selector">${Object.keys(names).map(p=>`<button data-market="${p}" class="${p===selected?'active':''}">${p.split('-')[0]}</button>`).join('')}</div></div><div class="chart-info"><span class="chart-price">${priceMoney(price)}</span><span class="chart-change ${tone(change)}">${percent(change)} <span class="muted">24h*</span></span></div><div class="chart-meta"><span>${chartHours}H CANDLES <span class="muted">·</span> LAST 72 BARS</span><span class="quote-status ${freshQuote()?'online':''}">${freshQuote()?'Live quote':'Saved candle close'} · ${esc(date(freshQuote()?quotes[selected].time:bars.at(-1)?.time))}</span></div><div class="chart">${chart()}</div><div class="chart-legend"><span><i class="legend-line" style="background:#b9f47a"></i>Support</span><span><i class="legend-line" style="background:#e6bb78"></i>Resistance</span><span><i class="legend-line" style="background:#8fdbe8"></i>Trendlines</span><span>*~24h change</span></div><div class="level-strip"><div><div class="label">Nearest support</div><div class="level-value positive">${priceMoney(a.support)}</div></div><div><div class="label">Nearest resistance</div><div class="level-value" style="color:var(--orange)">${priceMoney(a.resistance)}</div></div><div><div class="label">14-bar ATR</div><div class="level-value">${money(a.atr)}</div></div></div></section>`}
function signalPanel(){const a=analysis(),c=config(),hasLevels=!!(a.support&&a.resistance);return `<section class="panel signal-card"><div class="panel-head"><h2>The current setup</h2><span class="status">${c.strategy==='aggressive'?'AGGRESSIVE TRIAL':c.strategy==='trendline'?'4H / 1H TRENDLINE':'S/R BOUNCE'}</span></div><div class="signal-state ${a.signal==='BUY'?'buy':''}"><span aria-hidden="true">${a.signal==='BUY'?'◎':'◷'}</span>${a.signal==='BUY'?'Setup confirmed':'Scanning for the next setup.'}</div><p class="signal-desc">${esc(a.reason)}</p><div class="checklist"><div class="check-row ${hasLevels?'':'pending'}"><span>${hasLevels?'✓':'○'}</span>Confirmed price levels</div><div class="check-row ${a.signal==='BUY'?'':'pending'}"><span>${a.signal==='BUY'?'✓':'○'}</span>Bullish bounce & room to target</div><div class="check-row"><span>✓</span>${(c.riskPct*100).toFixed(1)}% risk budget per trade</div><div class="check-row"><span>✓</span>Fees & slippage included</div></div><button class="button primary" data-action="trade">Plan a paper trade</button><p class="signal-foot">Opens in your browser's practice account</p></section>`}
function spark(product){const data=candles(product).slice(-24).map(c=>c.close);if(!data.length)return '';const low=Math.min(...data),high=Math.max(...data),color=data.at(-1)>=data[0]?'#a9dc91':'#cb8174';return `<svg viewBox="0 0 60 28" width="100%" height="28" aria-hidden="true"><path d="${data.map((v,i)=>`${i?'L':'M'}${i*60/(data.length-1)},${25-(v-low)/(high-low||1)*22}`).join(' ')}" stroke="${color}" fill="none" stroke-width="1.5"/></svg>`}
function watchlist(){return `<section class="panel section-gap"><div class="panel-head"><h2>On your radar</h2><span class="muted small">Coinbase spot markets</span></div><div class="watchlist">${Object.keys(names).map(p=>{const bars=candles(p),change=bars.at(-25)?(prices()[p]-bars.at(-25).close)/bars.at(-25).close:NaN;return `<button class="watch-item" data-market="${p}"><span class="coin ${p.slice(0,3).toLowerCase()}">${symbols[p]}</span><div><div class="watch-name">${names[p]} <span class="muted">${p.slice(0,3)}</span></div><div class="watch-price">${priceMoney(prices()[p])}</div></div><div class="watch-spark">${spark(p)}</div><div class="watch-move ${tone(change)}">${percent(change)}</div></button>`}).join('')}</div></section>`}
function positionsPanel(){const positions=account().positions;return `<section class="panel"><div class="panel-head"><h2>Open positions <span class="muted small">${positions.length.toString().padStart(2,'0')}</span></h2><a class="text-link" href="#journal">View journal</a></div>${!positions.length?`<div class="empty-state"><span class="empty-icon">▱</span><h3>Room for your next good idea.</h3><p>No open paper positions. Wait for your setup, or plan a trade in your practice account.</p></div>`:`<div class="table-wrap"><table><thead><tr><th>MARKET</th><th>ENTRY</th><th>UNREALIZED*</th><th>STOP / TARGET</th>${accountMode==='personal'?'<th>ACTION</th>':''}</tr></thead><tbody>${positions.map(p=>{const pnl=((prices()[p.product]??p.entry)-p.entry)*p.quantity-p.entryFee;return `<tr><td>${esc(p.product)}<div class="small muted">${p.quantity.toFixed(6)} units</div></td><td>${money(p.entry)}</td><td class="${tone(pnl)}">${money(pnl)}</td><td>${money(p.stop)} / ${money(p.target)}</td>${accountMode==='personal'?`<td><button class="button secondary" data-close="${esc(p.id)}" ${freshQuote(p.product)?'':'disabled'}>Close paper trade</button></td>`:''}</tr>`}).join('')}</tbody></table></div><p class="small muted body-pad">*After entry fee; exit costs apply when closed.</p>`}</section>`}
function reviewSummary(){const last=currentReviews().reviews[0];return `<section class="panel review-summary"><span class="eyebrow">THE DAILY FEEDBACK LOOP</span><h3>${last?last.status==='promoted'?'New parameters, same discipline.':'Evidence before adjustment.':'Your next review starts here.'}</h3><p>${last?esc(last.reason):'The separate daily learning workflow reviews accumulated evidence once each UTC day.'}</p><a href="#updates" class="text-link">Explore daily reviews</a></section>`}
function overview(){return `${supervisorPanel()}${metrics()}${teamPanel()}${scorecardPanel()}<div class="main-grid">${marketPanel()}${signalPanel()}</div>${watchlist()}${patternPanel()}${strategyLabPanel()}${learningPanel()}<div class="bottom-grid">${positionsPanel()}${reviewSummary()}</div>`}
function journal(){const a=account(),trades=[...a.trades].reverse();return `${metrics()}${positionsPanel()}${decisionPanel()}<section class="panel section-gap"><div class="panel-head"><div><h2>Closed trades</h2><p>Results include modeled entry and exit fees and slippage.</p></div><button class="button secondary" data-action="export-csv">Export CSV</button></div>${!trades.length?'<div class="empty-state"><span class="empty-icon">≡</span><h3>A fresh page in your journal.</h3><p>Closed paper trades will appear here with their entry, exit, costs, and outcome.</p></div>':`<div class="table-wrap"><table><thead><tr><th>MARKET / CLOSED UTC</th><th>ENTRY</th><th>EXIT</th><th>FEES</th><th>NET P&L</th><th>ENTRY PATTERN</th><th>EXIT REASON</th></tr></thead><tbody>${trades.map(t=>`<tr><td>${esc(t.product)}<div class="small muted">${date(t.closedAt)}</div></td><td>${money(t.entry)}</td><td>${money(t.exit)}</td><td>${money(t.fees)}<div class="small muted">${esc(t.entryFeeDetail?.liquidity??"legacy")} / ${esc(t.exitFeeDetail?.liquidity??"legacy")} · rebate credited ${money(t.rebateCredited??0)} · pending ${money(t.rebatePending??0)} · net cost ${money(t.fees-(t.rebateCredited??0))}</div></td><td class="${tone(t.pnl)}">${money(t.pnl)}</td><td>${esc(t.pattern?.status==='evaluated'?(t.pattern.confirmed?t.pattern.matches.join(', '):'No confirmation'):'Not recorded at entry')}</td><td>${esc(t.reason)}</td></tr>`).join('')}</tbody></table></div>`}</section><p class="prose">${accountMode==='private'?'The encrypted account uses a read-only Coinbase starting snapshot. Entries, exits, and every hourly decision are simulated. No real funds move.':accountMode==='shared'?'The scheduled account lives in your repository. Five-minute GitHub Actions checks process newly completed hourly candles and publish its latest state.':'Your practice account is stored on this browser and device. Exits are checked when you open or refresh the app; it does not run while closed.'}</p>`}
function legacyStrategy(){const c=config(),b=backtestResult;return `<section class="panel"><div class="strategy-banner"><div class="eyebrow">THE PLAYBOOK</div><h2>Buy the bounce. Respect the level.</h2><p>A long-only spot strategy that waits for confirmed support, bullish price action, and sufficient room below resistance after estimated costs.</p></div><div class="body-pad cards-two"><div><h3>How a signal becomes a trade</h3><p class="prose"><strong>1. Find the structure.</strong> Confirm swing highs and lows using ${c.pivotWindow} completed bars on either side, across a ${c.lookback}-bar lookback.<br><strong>2. Wait for confirmation.</strong> Price must revisit support and close bullish above the previous close.<br><strong>3. Check the economics.</strong> The target must fit below resistance at ${c.rewardRisk.toFixed(1)}:1 reward/risk, after costs.<br><strong>4. Simulate execution.</strong> Scheduled entries fill at the next candle open. Stops win if both exits are touched in a candle.</p></div><div><h3>Current guardrails</h3><p class="prose">Risk budget: <strong>${c.riskPct*100}% of paper equity</strong><br>Allocation cap: <strong>${c.maxAllocation*100}% per position</strong><br>Estimated fee: <strong>${(c.feeRate*100).toFixed(2)}% each side</strong><br>Adverse slippage: <strong>${(c.slippage*100).toFixed(2)}% each side</strong><br>Stop buffer below support: <strong>${(c.stopBuffer*100).toFixed(2)}%</strong><br>Markets: <strong>${accountMode==='shared'?'BTC-USD automated · ETH/SOL watchlist':'BTC, ETH, SOL · manual practice'}</strong></p></div></div></section><div class="cards-two section-gap"><section class="panel"><div class="panel-head"><div><h2>Historical replay</h2><p>Test the current parameters on saved hourly candles.</p></div></div><div class="body-pad"><label>Market<select id="backtest-product">${Object.keys(names).map(p=>`<option ${selected===p?'selected':''}>${p}</option>`).join('')}</select></label><p class="small muted">${candles().length} available closed bars for ${selected}. Results are a simulation, separate from your paper account.</p><button class="button primary" data-action="backtest">Run historical replay</button>${b?`<div class="review-metrics"><div><span class="label">Net return</span><div class="${tone(b.returnPct)}">${percent(b.returnPct)}</div></div><div><span class="label">Max drawdown</span><div>${percent(-b.drawdown)}</div></div><div><span class="label">Closed trades</span><div>${b.closedTrades}</div></div></div><p class="small muted">${b.candles} bars · ${esc(b.product)} · ${money(b.totalFees)} fees · ${date(b.start)} to ${date(b.end)}</p>`:''}</div></section><section class="panel"><div class="panel-head"><div><h2>Parameter review</h2><p>Training first. A later holdout second.</p></div></div><div class="body-pad"><p class="prose">Compare a small, fixed set of lookbacks and entry zones. A candidate needs at least five closed trades in every comparison sample and no higher holdout drawdown.</p><button class="button secondary" data-action="review">Run research review</button>${localReview?`<p class="prose"><strong>${esc(localReview.status)}</strong><br>${esc(localReview.reason)}</p><p class="small muted">This manual review does not change the scheduled account.</p>`:''}</div></section></div><div class="info-box section-gap">The scheduled daily review uses rolling historical data. Repeated testing can overfit; its holdout is a research check, not a guarantee of future returns. Parameters are only adopted for future paper entries.</div>`}
function updates(){const visiblePaper=accountMode==='private'?(getPrivateState()??paper):paper;const activeReviews=currentReviews();const latest=activeReviews.reviews[0];return `${evidencePanel()}${patternPanel()}${strategyLabPanel()}${learningPanel()}<div class="metrics">${metric('Review cadence','Daily','Once per UTC day, during a scheduled run','◷')}${metric('Last review',latest?esc(latest.date):'Pending',latest?esc(latest.status):'Run the GitHub update workflow','◫')}${metric('Parameter changes',String(activeReviews.reviews.filter(r=>r.status==='promoted').length),'Recorded promotions in retained history','⌘')}${metric('Account updated',visiblePaper.updatedAt?new Date(visiblePaper.updatedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'}):'—',`${esc(visiblePaper.updatedAt?.slice(0,10)??'Not yet')} · schedule is best effort`,'⟳')}</div><div class="info-box">Daily reviews evaluate each enabled market. When a candidate passes the checks, the workflow saves its exact changes for future paper trades. It keeps the current configuration when evidence is insufficient. <a class="text-link" href="${repo}/actions/workflows/update.yml" target="_blank" rel="noopener">View workflow runs ↗</a></div>${(visiblePaper.errors??market.errors??[]).map(e=>`<div class="info-box" style="border-color:var(--orange)"><strong>${esc(e.product)}</strong> · ${esc(e.message)}<br>${esc(date(e.time))}</div>`).join('')}<section class="panel"><div class="panel-head"><h2>Research & change history</h2><span class="muted small">Latest first</span></div>${!activeReviews.reviews.length?'<div class="empty-state"><span class="empty-icon">◷</span><h3>No reviews yet.</h3><p>The first successful market update will create a dated review with real test results.</p></div>':activeReviews.reviews.map(r=>{const changes=Object.keys(r.after??{}).filter(k=>r.after[k]!==r.before?.[k]);return `<article class="review-item"><div class="review-top"><span class="small muted">${esc(date(r.time))} · ${esc(r.product)}</span><span class="status ${r.status==='promoted'?'':'wait'}">${esc(r.status==='promoted'?'PARAMETERS UPDATED':r.status==='retained'?'PARAMETERS RETAINED':'MORE DATA NEEDED')}</span></div><h3>${r.status==='promoted'?'A candidate cleared the research checks.':'Keep collecting evidence.'}</h3><p>${esc(r.reason)}</p>${r.outcomes?`<p class="small muted">Closed: ${r.outcomes.closedTrades??0} · Net P&L: ${money(r.outcomes.pnl??0)} · Fees: ${money(r.outcomes.fees??0)}</p>`:''}${Array.isArray(r.outcomes?.lessons)?`<p class="prose">${r.outcomes.lessons.map(esc).join('<br>')}</p>`:''}${changes.length?`<div class="change-code">${changes.map(k=>`${esc(k)}: ${esc(r.before[k])} → ${esc(r.after[k])}`).join('\n')}</div>`:''}${r.baseline?`<div class="review-metrics"><div><span class="label">Holdout baseline</span><div>${percent(r.baseline.returnPct)} · ${r.baseline.closedTrades} trades</div></div><div><span class="label">Holdout candidate</span><div>${percent(r.candidate?.returnPct)} · ${r.candidate?.closedTrades??0} trades</div></div><div><span class="label">Sample</span><div>${r.training?.candles??0} train / ${r.holdout?.candles??0} holdout bars</div></div></div>`:''}</article>`}).join('')}</section><section class="panel section-gap"><div class="panel-head"><h2>Build log</h2><span class="status">v2.0</span></div><div class="body-pad prose">Automated lab release: support/resistance detection, paper execution engine, persistent practice account, scheduled virtual account, daily research reviews, CSV exports, and responsive iPad layout.<br><a class="text-link" href="${repo}/commits/main" target="_blank" rel="noopener">See code changes on GitHub ↗</a></div></section>`}
function settings(){const c=personalConfig;return `<div class="info-box">These controls affect <strong>your browser's practice account</strong>. The public demo account uses the versioned configuration in <code>data/paper.json</code>. All balances in this app are virtual.</div><div class="cards-two"><section class="panel"><div class="panel-head"><h2>Practice risk settings</h2><span class="status">BROWSER ONLY</span></div><form class="body-pad" id="settings-form"><div class="form-grid"><label>Risk per trade · %<input name="riskPct" type="number" min="0.1" max="5" step="0.1" value="${c.riskPct*100}" required></label><label>Max allocation · %<input name="maxAllocation" type="number" min="1" max="100" step="1" value="${c.maxAllocation*100}" required></label><label>Estimated fee per side · %<input name="feeRate" type="number" min="0" max="5" step="0.01" value="${c.feeRate*100}" required></label><label>Slippage per side · %<input name="slippage" type="number" min="0" max="5" step="0.01" value="${c.slippage*100}" required></label><label>Reward / risk ratio<input name="rewardRisk" type="number" min="0.5" max="10" step="0.1" value="${c.rewardRisk}" required></label><label>Level lookback · bars<input name="lookback" type="number" min="12" max="300" step="1" value="${c.lookback}" required></label></div><div class="form-actions"><button class="button primary" type="submit">Save practice settings</button><button class="button ghost" type="button" data-action="defaults">Restore defaults</button></div><p class="small muted">Open positions keep their original fee and slippage assumptions.</p></form></section><section class="panel"><div class="panel-head"><h2>Your data & connections</h2></div><div class="body-pad"><h3>Coinbase market data</h3><p class="prose">The initial market snapshot was collected through your Coinbase MCP. This static app refreshes prices directly from Coinbase's public Exchange API. Your separately encrypted starting snapshot was read through Coinbase MCP. Hourly jobs use public prices only and do not resync your real balances or place orders.</p><h3>Practice account backup</h3><p class="prose">Browser data stays on this device. Export a JSON backup to keep your trades. CSV is available in the trade journal.</p><div class="form-actions"><button class="button secondary" data-action="export-json">Export practice backup</button></div><p class="prose">The public demo account is committed in plain text. Your portfolio-matched account and its journal are encrypted before commit; its unlock key stays outside source. GitHub Actions schedules can be delayed and may disable after prolonged repository inactivity.</p><button class="button ghost negative" data-action="reset">Reset practice account</button><p class="small muted">Reset restores $10,000 virtual cash after confirmation.</p></div></section></div>`}

function render(){
  const key=page(),[label,title,subtitle]=pages[key];$('#breadcrumb').textContent=label;$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;document.title=`${label} · Level Lab`;
  $$('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===key);if(el.dataset.nav===key)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});
  $$('[data-account]').forEach(el=>{el.classList.toggle('active',el.dataset.account===accountMode);el.setAttribute('aria-pressed',String(el.dataset.account===accountMode))});
  $('#account-note').textContent=accountMode==='private'?'Encrypted portfolio simulation · snapshot baseline':accountMode==='shared'?'two-hour checks · hourly paper fills':'Local to this browser · manual entries';$('#journal-count').textContent=account().trades.length;
  $('#view').innerHTML=accountMode==='private'&&!getPrivateState()?renderPrivatePanel(prices()):(accountMode==='private'&&['overview','settings'].includes(key)?renderPrivatePanel(prices()):'')+({overview,journal,strategy,updates,settings}[key])();dataWarning();
}
async function planTrade(){
  accountMode='personal';render();if(!freshQuote()){await refresh(true);if(!freshQuote()){notify('A fresh Coinbase quote is required. Refresh the market feed and try again.');return}}
  if(personal.positions.some(p=>p.product===selected)){notify('This market already has an open practice position.');return}
  const a=analysis(),p=quotes[selected].price;
  $('#trade-reference').innerHTML=`${esc(selected)} · ${money(p)}<small>Coinbase quote ${esc(date(quotes[selected].time))} · virtual fill</small>`;
  $('#trade-stop').value=(a.stop&&a.stop<p?a.stop:p*.98).toFixed(['BTC-USD','ETH-USD'].includes(selected)?2:6);$('#trade-target').value=(a.target&&a.target>p?a.target:p*1.04).toFixed(['BTC-USD','ETH-USD'].includes(selected)?2:6);
  $('#trade-risk').textContent=`Risk budget up to ${money(markToMarket(personal,prices()).equity*personalConfig.riskPct)}; ${(personalConfig.maxAllocation*100).toFixed(0)}% allocation cap. This is a manual practice trade, even when the strategy says wait.`;$('#trade-error').textContent='';$('#trade-dialog').showModal();
}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const actions={
  trade:planTrade,
  'lock-private':()=>{lockPrivate();render();notify('Private portfolio locked. The key and decrypted state were cleared from memory.');},
  backtest:()=>{selected=$('#backtest-product').value;const bars=candles();if(bars.length<48)return notify('At least 48 completed candles are needed.');backtestResult={...backtest(bars,config()),product:selected,start:bars[0].time,end:bars.at(-1).time};render()},
  review:()=>{localReview=reviewStrategy(candles(),config());render()},
  defaults:()=>{personalConfig={...DEFAULT_CONFIG};persist();render();notify('Practice settings restored.')},
  reset:()=>{if(confirm('Reset this browser’s practice account to $10,000? This removes its positions and trade history. Export a backup first if needed.')){personal=createAccount();persist();render();notify('Practice account reset.')}},
  'export-json':()=>download('level-lab-practice.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),account:personal,config:personalConfig},null,2),'application/json'),
  'export-csv':()=>{const fields=['id','product','openedAt','closedAt','entry','exit','quantity','fees','pnl','reason'];const csv=[fields.join(','),...account().trades.map(t=>fields.map(k=>'"'+String(t[k]??'').replaceAll('"','""')+'"').join(','))].join('\n');download('level-lab-trades.csv',csv,'text/csv')}
};
document.addEventListener('click',async event=>{
  const marketButton=event.target.closest('[data-market]');if(marketButton){selected=marketButton.dataset.market;backtestResult=null;localReview=null;render();return}
  const hoursButton=event.target.closest('[data-hours]');if(hoursButton){chartHours=+hoursButton.dataset.hours;render();return}
  const modeButton=event.target.closest('[data-account]');if(modeButton){accountMode=modeButton.dataset.account;render();return}
  const action=event.target.closest('[data-action]');if(action){try{await actions[action.dataset.action]?.()}catch(error){notify(error.message)}return}
  const close=event.target.closest('[data-close]');if(close){const p=personal.positions.find(p=>p.id===close.dataset.close);if(!p||!freshQuote(p.product))return notify('Refresh for a fresh quote before closing.');closePaperTrade(personal,p.id,quotes[p.product].price,Date.now()/1000,'manual',personalConfig);persist();render();notify('Virtual position closed.');}
});
document.addEventListener('submit',event=>{
  if(event.target.id!=='settings-form')return;event.preventDefault();const data=new FormData(event.target),next={...personalConfig};for(const key of ['riskPct','maxAllocation','feeRate','slippage'])next[key]=+data.get(key)/100;for(const key of ['rewardRisk','lookback'])next[key]=+data.get(key);try{analyze(candles(),next);personalConfig=next;persist();render();notify('Practice settings saved.')}catch(error){notify(error.message)}
});
$('#trade-form').addEventListener('submit',event=>{event.preventDefault();try{if(!freshQuote())throw new Error('Quote expired. Close this dialog and refresh before opening a trade.');openPaperTrade(personal,{product:selected,price:quotes[selected].price,stop:+$('#trade-stop').value,target:+$('#trade-target').value,time:Date.now()/1000,source:'manual practice'},personalConfig);persist();$('#trade-dialog').close();render();notify('Virtual position opened.')}catch(error){$('#trade-error').textContent=error.message}});
$('#close-dialog').addEventListener('click',()=>$('#trade-dialog').close());$('#refresh').addEventListener('click',()=>refresh());window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'smooth'})});
$('#view').innerHTML='<div class="loading">Loading your trading workspace…</div>';
await loadSnapshots();render();refresh(true);setInterval(()=>{if(!document.hidden&&!$('#trade-dialog').open&&page()!=='settings')refresh(true)},60000);
startLiveTicker();

document.addEventListener('change',async event=>{if(event.target.id!=='private-key-file')return;const file=event.target.files?.[0];if(!file)return;try{await unlockPrivate(await file.text(),json);accountMode='private';selected='XRP-USD';render();notify('Encrypted paper portfolio unlocked on this tab.');}catch{notify('Unable to unlock. Use the private paper-state key file; no data was saved.');}});

function decisionPanel(){
  const a=account(),decisions=[...(a.decisions??[])].reverse().slice(0,160);
  return `<section class="panel section-gap"><div class="panel-head"><div><h2>Decision log — these are not orders</h2><p>WAIT and SYNC are monitoring decisions. Actual virtual fills appear under Open positions and Closed trades. Latest 160 shown.</p></div><span class="status">${a.decisions?.length??0} ENTRIES</span></div>${!decisions.length?'<div class="empty-state"><h3>Recording starts with the next processed candle.</h3><p>Waiting, risk-limit skips, entries, and exits will appear here. No historical trades are invented.</p></div>':`<div class="table-wrap"><table><thead><tr><th>UTC / MARKET</th><th>ACTION</th><th>SETUP / REASON</th><th>REFERENCE</th></tr></thead><tbody>${decisions.map(d=>`<tr><td>${esc(date(d.time))}<div class="small muted">${esc(d.product)}</div></td><td>${esc(d.action??d.signal??'CHECK')}</td><td style="white-space:normal;min-width:240px;max-width:480px">${esc(d.reason)}<div class="small muted">${esc(d.setup??d.strategy??'Hourly review')}</div><div class="small muted">Entry pattern: ${esc(d.pattern?.status==='evaluated'?(d.pattern.confirmed?d.pattern.matches.join(', '):'no confirmation'):'not recorded')}</div></td><td>${money(d.price)}<div class="small muted">S ${money(d.support)} / R ${money(d.resistance)}</div></td></tr>`).join('')}</tbody></table></div>`}</section>`;
}

function strategy(){
  if(config().strategy==='trend-follow')return trendStrategy();
  if(config().strategy==='aggressive')return experimentalStrategy();
  if(config().strategy!=='trendline')return legacyStrategy();
  const c=config(),b=backtestResult;
  return `<section class="panel"><div class="strategy-banner"><div class="eyebrow">TORI-INSPIRED · MECHANICAL APPROXIMATION</div><h2>Trade structure. Define the invalidation.</h2><p>Four-hour trendlines establish the setup. One-hour completed candles confirm entries and manage paper positions. This is an explicit algorithmic research model, not an endorsed or exact reproduction of Tori's discretionary method.</p></div><div class="body-pad cards-two"><div><h3>Entry and exit rules</h3><p class="prose">Detect confirmed swing highs and lows, fit lines with at least three separated touches, and look for rising-support bounces or descending-resistance breaks. A bullish hourly close must confirm the setup. A stop defines invalidation, and the next resistance must allow at least <strong>${c.rewardRisk??2}:1 net reward/risk</strong> after modeled costs. Stops, targets, and a ${c.maxHoldHours??48}-hour time exit manage open paper trades.</p><p class="prose">This is long-only spot simulation. The scanner evaluates a fixed liquid universe—XRP, SOL, ETH, BTC, ADA, DOGE, LINK, and AVAX—and buys only qualifying bullish setups. An hourly check does not guarantee an hourly trade.</p></div><div><h3>Portfolio guardrails</h3><p class="prose">New-trade stop-risk budget: <strong>${((c.riskPct??.01)*100).toFixed(1)}%</strong><br>Aggregate planned risk cap: <strong>${((c.maxTotalRisk??.03)*100).toFixed(1)}%</strong><br>Maximum open positions: <strong>${c.maxOpenPositions??4}</strong><br>Daily loss pause: <strong>${((c.maxDailyLoss??.04)*100).toFixed(1)}%</strong><br>Estimated fee: <strong>${((c.feeRate??.006)*100).toFixed(2)}% per side</strong><br>Slippage: <strong>${((c.slippage??.0005)*100).toFixed(2)}% per side</strong></p><p class="small muted">Stops are modeled hourly, not guaranteed fills. Gaps and delayed scheduled runs can exceed intended risk. Existing seed holdings and initial exploration trades are labeled separately from confirmed signals.</p></div></div></section><div class="cards-two section-gap"><section class="panel"><div class="panel-head"><div><h2>Historical replay</h2><p>Evaluate the current rules on completed market candles.</p></div></div><div class="body-pad"><label>Market<select id="backtest-product">${Object.keys(names).map(p=>`<option ${selected===p?'selected':''}>${p}</option>`).join('')}</select></label><p class="small muted">${candles().length} saved hourly bars for ${esc(selected)}. Four-hour structure needs sufficiently long history.</p><button class="button primary" data-action="backtest">Run historical replay</button>${b?`<div class="review-metrics"><div>Net return <span class="${tone(b.returnPct)}">${percent(b.returnPct)}</span></div><div>Drawdown ${percent(-b.drawdown)}</div><div>${b.closedTrades} closed trades</div></div><p class="small muted">${b.candles} hourly bars · ${esc(b.product)} · ${money(b.totalFees)} fees</p>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Daily learning loop</h2></div><div class="body-pad"><p class="prose">The scheduler records closed trades, fees, losing exit patterns, missed or rejected setups, and research candidates. Parameter changes require training and later-holdout checks with sufficient samples. It can retain the current setup when evidence is weak.</p><button class="button secondary" data-action="review">Run research review</button>${localReview?`<p class="prose"><strong>${esc(localReview.status)}</strong><br>${esc(localReview.reason)}</p>`:''}<p class="small muted">Daily research is a rules-based retrospective, not unattended web browsing or a promise of daily improvement.</p></div></section></div><section class="panel section-gap"><div class="body-pad prose">Method references: <a class="text-link" href="https://toritradez.com/blog/all/perfect-trade-trend-line-setup" target="_blank" rel="noopener">Tori's action/safety trendlines</a> and <a class="text-link" href="https://toritradez.com/blog/all/trend-line-trading-masterclass-a-to-z" target="_blank" rel="noopener">four-hour/top-down framework</a>. Pivot windows, time exits, and automated filters are our modeling choices. The $85,000 target is a paper research goal; simulated gains do not repair the real Coinbase portfolio.</div></section>`;
}

function learningPanel(){const model=accountMode==='private'?getPrivateState()?.learning:learning;if(!model)return '';const h=model.holdout,p=model.predictions?.[selected];return `<section class="panel section-gap"><div class="panel-head"><h2>Machine learning · shadow experiment</h2><span class="status">${esc(model.status)}</span></div><div class="body-pad prose">${esc(model.model??model.reason??'Waiting for model output.')}<br>${h?`Training ${model.trainSamples} samples / later holdout ${model.holdoutSamples}. Brier loss ${h.brier.toFixed(4)} vs constant baseline ${h.baselineBrier.toFixed(4)}. ${h.beatsConstantBaseline?'Lower held-out probability error.':'Did not beat the constant baseline.'}`:''}${p?`<br>${esc(selected)}: ${(p.probability*100).toFixed(1)}% modeled chance of exceeding the four-hour fee hurdle. As of ${esc(date(p.time))}.`:''}<p class="small muted">Shadow only. This is not a guaranteed win rate and does not control entries. Trained on historical market labels; chronological holdout and a four-hour label embargo prevent future labels crossing the split.</p></div></section>`;}
function startLiveTicker(){
 if(typeof window.WebSocket==='undefined')return;let socket,retry=0,renderTimer;
 const connect=()=>{socket=new window.WebSocket('wss://ws-feed.exchange.coinbase.com');socket.onopen=()=>{retry=0;socket.send(JSON.stringify({type:'subscribe',product_ids:Object.keys(names),channels:['ticker']}));};
 socket.onmessage=event=>{try{const tick=JSON.parse(event.data),t=Date.parse(tick.time);if(tick.type!=='ticker'||!Object.hasOwn(names,tick.product_id)||!Number.isFinite(+tick.price)||+tick.price<=0||!Number.isFinite(t)||Date.now()-t>120000||t-Date.now()>30000)return;quotes[tick.product_id]={price:+tick.price,time:tick.time,receivedAt:Date.now()};if(!renderTimer)renderTimer=setTimeout(()=>{renderTimer=null;if(!document.hidden&&!$('#trade-dialog').open&&!(accountMode==='private'&&!getPrivateState())&&['overview','journal'].includes(page()))render();},1000);}catch{}};
 socket.onerror=()=>socket.close();socket.onclose=()=>setTimeout(connect,Math.min(30000,1000*2**Math.min(retry++,5)));};connect();
}

function trendStrategy(){const c=config();return `<section class="panel"><div class="strategy-banner"><div class="eyebrow">MAIN RULES · TREND FOLLOWING</div><h2>Ride the leaders. Trail the stop.</h2><p>Long-only spot paper trading on a fixed eight-coin universe, using two years of stored Coinbase 6h and daily candles.</p></div><div class="body-pad cards-two"><div><h3>Entry and exit</h3><p class="prose"><strong>Trend test:</strong> daily close above its 50-day EMA and the 20-day EMA above the 50-day.<br><strong>Trigger:</strong> a 6h close at a new ${c.trendBreakout??20}-bar closing high. Coinbase has no 4h candles, so 6h is used.<br><strong>Rank:</strong> only the top ${c.trendTopN??2} trend-passing coins by ${c.trendRankDays??30}-day return may be bought.<br><strong>Entry:</strong> ${c.entryOrder==='limit'?'a paper limit buy just below bid/last, filled as maker only if a later quote trades at or below it':'a paper market buy'}.<br><strong>Exit:</strong> chandelier trailing stop, highest close since entry minus ${c.trailAtrMultiplier??3}×ATR. It only moves up. No fixed target, no time exit.</p></div><div><h3>Risk</h3><p class="prose">Equal risk per position: ${((c.riskPct??.01)*100).toFixed(1)}% of equity divided by the ATR stop distance<br>Aggregate planned risk cap: ${((c.maxTotalRisk??.03)*100).toFixed(1)}%<br>At most 60% of equity invested<br>Drawdown: 10% below peak halves new sizes, 15% blocks entries until cleared<br>Daily loss pause: ${((c.maxDailyLoss??.04)*100).toFixed(1)}%</p><p class="small muted">Backtests and paper results are not a promise of future profit.</p></div></div></section>${learningPanel()}`;}
function experimentalStrategy(){const c=config();return `<section class="panel"><div class="strategy-banner"><div class="eyebrow">AGGRESSIVE PAPER EXPERIMENT</div><h2>Generate evidence. Measure the mistakes.</h2><p>This is not a confirmed Tori strategy. Exploration entries use bullish hourly candles, a widened support zone, or countertrend pullbacks, with cost-aware targets and short time exits.</p></div><div class="body-pad prose">Risk budget per trade: ${(c.riskPct*100).toFixed(1)}%; aggregate planned risk ${(c.maxTotalRisk*100).toFixed(1)}%; ${c.maxOpenPositions} positions; maximum hold ${c.maxHoldHours} hours; daily-loss entry pause ${(c.maxDailyLoss*100).toFixed(1)}%. New trades execute at the fresh quote when a check actually runs, not at an earlier candle open. Failed/stale quotes pause the entire account. A model prediction is recorded in shadow mode, not treated as a promise or a validated trading edge.<br><br>Price ticks can update while this page is open even when the server timer is stopped. Check the server timestamp and scheduler warning. User portfolio balances stay encrypted.</div></section>${learningPanel()}`;}

function evidencePanel(){const state=accountMode==='private'?getPrivateState():null,e=state?.evidence??(accountMode==='private'?{}:evidence),r=state?.journalResearch??(accountMode==='private'?{}:research),hour=e.hourly?.at(-1),m=r.tradeModel;return `<section class="panel section-gap"><div class="panel-head"><div><h2>Collect first. Review once daily.</h2><p>Trading checks: configured every 2 hours · Evidence: hourly · Strategy review: daily 00:37 UTC</p></div></div><div class="body-pad prose">Evidence collected: ${esc(date(e.lastCollectedAt))}<br>${e.allTime?`Cumulative completed evidence: <strong>${e.allTime.closedTrades} trades, ${e.allTime.wins} wins, ${e.allTime.losses} losses, ${e.allTime.flats} flat.</strong> Net ${money(e.allTime.netPnl)} after modeled costs; snapshot rebalances excluded.<br>`:''}${hour?`Last completed hour ${esc(date(hour.periodStart))} to ${esc(date(hour.periodEnd))}: <strong>${hour.closedTrades} closed trades, ${hour.wins} wins, ${hour.losses} losses, ${hour.flats} flat.</strong> Net ${money(hour.netPnl)}, gross fees ${money(hour.grossFees)}, credited rebates ${money(hour.rebatesCredited)}. ${hour.evidenceComplete?'':'Execution heartbeat was incomplete for this hour; absence of recorded trades does not prove the trader ran.'}`:'No completed hourly collection yet.'}<br>Daily review: ${esc(r.reviewDate??'Not yet')} · ${r.outcomes?`${r.outcomes.closedTrades} previous-day closes, ${r.outcomes.wins} wins and ${r.outcomes.losses} losses.`:'Waiting for the daily job.'}<br>${m?`Own-trade ML: ${esc(m.status)} · ${m.eligibleClosedTrades} eligible feature-frozen closed trades / ${m.minimumRequired} minimum. ${esc(m.reason)}`:'Own-trade ML waits for enough executed outcomes; the market-label shadow model below is separate.'}<p class="small muted">Collection never opens or closes positions. Daily review retains parameters when evidence is insufficient; risk caps remain fixed. This is not automatic code rewriting or guaranteed profit.</p>${r.proposals?.length?`<div class="table-wrap"><table><thead><tr><th>MARKET</th><th>DAILY DECISION</th><th>WHY</th></tr></thead><tbody>${r.proposals.map(p=>`<tr><td>${esc(p.product)}</td><td>${esc(p.status)}</td><td style="white-space:normal">${esc(p.reason)}</td></tr>`).join('')}</tbody></table></div>`:''}</div></section>`;}

function patternPanel(){
 const state=accountMode==='private'?getPrivateState():accountMode==='shared'?paper:{};if(!state)return '';
 const report=state.journalResearch?.patternResearch?.[selected]??state.patternResearch?.products?.[selected];
 const current=patternConfirmation(market.products?.[selected]?.candles??[]),outcomes=state.evidence?.allTime?.byPattern??{};
 const arm=r=>r?`${percent(r.returnPct)} net return · ${r.closedTrades} closes · ${percent(r.drawdown)} drawdown · ${money(r.totalFees)} gross fees`:'Not available';
 return `<section class="panel section-gap"><div class="panel-head"><div><h2>Day-trade patterns · entry research</h2><p>${esc(selected)} · completed 1-hour crypto candles</p></div><span class="status">OBSERVE ONLY</span></div><div class="body-pad prose"><strong>${current.status==='evaluated'?(current.confirmed?'Pattern confirmation: '+esc(current.matches.join(', ')):'No pattern confirmation') :esc(current.status)}</strong><br>${esc(current.reason)}${current.levels?` Reference closing high ${money(current.levels.closingHigh20)} · MA20 ${money(current.levels.ma20)}.`:''} As of ${esc(date(current.asOf))}.${current.volumeRatio!=null?` Volume ${current.volumeRatio.toFixed(2)}× the prior 20-hour average.`:''}${current.context.length?` Context: ${current.context.map(esc).join(', ')}.`:''}<p>The existing paper engine keeps trading. Each new automated entry freezes its pattern evidence; observation alone does not filter orders or change risk limits.</p>${report?`<strong>Fixed baseline vs pattern-filter replay: ${esc(report.status)}</strong><br>${report.candles} historical hourly candles; as of ${esc(date(report.asOf))}. ${esc(report.reason??report.recommendation)}${report.holdout?`<br>Later holdout ${esc(date(report.holdout.start))} to ${esc(date(report.holdout.end))}<br>Current strategy: ${arm(report.holdout.baseline)}<br>With pattern required: ${arm(report.holdout.filtered)}`:''}`:'First comparison pending.'}<br>Forward closed-trade evidence: confirmed ${outcomes.confirmed?.trades??0}, unconfirmed ${outcomes['not-confirmed']?.trades??0}, legacy/unrecorded ${outcomes['not-recorded']?.trades??0}.<p class="small muted">Adapted from day-trader-skill scanner/entry/exit/time-machine guidance. No US opening-bell assumption, broker integration, Monte Carlo claim or promised edge. Replay uses existing costs, slippage and conservative stop/target handling; hourly replay differs from two-hour quote execution. Comparisons refresh in the daily learning job.</p></div></section>`;
}

function strategyLabPanel(){
 const state=accountMode==='private'?getPrivateState():accountMode==='shared'?paper:null,r=state?.strategyLab;if(!r)return '';
 const p=r.products?.[selected],o=r.outcomes,m=r.models;
 return `<section class="panel section-gap"><div class="panel-head"><h2>Strategy research lab</h2><span class="status ${p?.decision?.startsWith('adopt')?'':'wait'}">${esc(r.experiment)} · ${esc(p?.decision??'pending')}</span></div><div class="body-pad prose">Updated ${esc(date(r.updatedAt))}. Re-researched every five hours; the two-hour trader uses the adopted rules per market.<br>${p?.selected?`<strong>${esc(selected)} rules in use: ${esc(p.decision?.startsWith('adopt')?p.selected:'unchanged')}</strong> · ${esc(p.reason)}<br>`:''}${(r.diagnosis?.findings??[]).length?`<strong>Why trades lost:</strong> ${r.diagnosis.findings.map(esc).join(' ')}<br>`:''}${o.closedTrades} closes · ${o.wins} wins · ${o.losses} losses · Net ${money(o.netPnl)}. Gross fees ${money(o.grossFees)}, credited rebates ${money(o.rebatesCredited)}. ${r.costDiagnosis.costFlippedLosses} losses had positive price P&amp;L before costs.<br>Trade-outcome models: ${esc(m.status)} · ${m.eligible}/${m.minimum} eligible closes. ${esc(m.reason)}<br>${p?`${esc(selected)}: ${esc(p.status)}. Selected in development: ${esc(p.selected??'pending')}. ${esc(p.reason??'')}`:''}
 ${p?.finalTest?`<p>Final historical test: selected ${percent(p.finalTest.candidate.returnPct)} / current ${percent(p.finalTest.baseline.returnPct)}; selected ${p.finalTest.candidate.closedTrades} closes, drawdown ${percent(p.finalTest.candidate.drawdown)}. No-rebate / double-slippage stress: ${percent(p.stress.returnPct)}. ${p.passed?'Profitable on the unseen window after costs and stress; adopted.':'No validated replacement.'}</p>`:''}
 ${p?.development?`<details><summary>Compare every approach tested this run</summary>${p.development.map(v=>`<p><strong>${esc(v.id)}</strong>: ${v.folds.map(f=>`${percent(f.returnPct)} net, ${f.closedTrades} closes`).join(' / ')} · ${v.eligible?'sample threshold met':'insufficient sample'}</p>`).join('')}</details>`:''}
 ${p?.forward?`<p>New forward replay: ${percent(p.forward.candidate.returnPct)} / current ${percent(p.forward.baseline.returnPct)}, ${p.forward.candidate.closedTrades} selected closes. ${p.forward.passed?'Forward numerical guard passed; daily adoption review still required.':'More evidence or a stronger result required.'}</p>`:''}
 <p class="small muted">${r.limitations.map(esc).join(' ')}</p></div></section>`;
}

/** Net-after-fee scorecard for the main account and its challengers, drawdown pause and goal estimate. */
function scorecardPanel(){
 const state=accountMode==='private'?getPrivateState():accountMode==='shared'?paper:null;if(!state?.account)return '';
 const px=prices(),pf=v=>v===Infinity?'no losses':Number.isFinite(v)?v.toFixed(2):'—',pct=v=>Number.isFinite(v)?(v*100).toFixed(1)+'%':'—';
 const rows=[{id:'main',label:`Main rules · ${state.config?.strategy??'—'}`,account:state.account,pause:state.pause},...(state.challengers??[]).filter(c=>c.account).map(c=>({id:c.id,label:c.label??c.id,account:c.account,pause:c.pause,since:c.rulesSince}))];
 const pauseText=p=>!p?.state||p.state==='normal'?'<span class="positive">normal</span>':p.state==='halved'?`<span class="neutral" style="color:var(--orange)">sizes halved · ${pct(p.drawdown)} below peak</span>`:`<span class="negative">entries blocked · ${pct(p.drawdown)} below peak</span>`;
 const g=goalEstimate(state.account,{goal:85000,prices:px}),main=state.pause;
 const eta=g.status==='estimated'?`<strong>${g.days<3650?Math.ceil(g.days)+' days':'over 10 years'}</strong> (around ${esc(g.date)}), from ${(g.dailyGrowth*100).toFixed(3)}%/day over the last ${g.spanDays.toFixed(0)} days`:g.status==='reached'?'<strong>Goal reached in paper equity.</strong>':`<strong>No estimate yet.</strong> ${esc(String(g.message).replace(/\.$/,''))}`;
 const body=rows.map(r=>{const st=performanceStats(r.account),eq=markToMarket(r.account,px).equity;return `<tr><td style="white-space:normal;min-width:180px">${esc(r.label)}${r.since?`<div class="small muted">rules since ${esc(date(r.since))}</div>`:''}</td><td>${money(eq)}<div class="small ${tone(eq-r.account.initial)}">${percent((eq-r.account.initial)/r.account.initial)}</div></td><td class="${tone(st.netPnl)}">${money(st.netPnl)}<div class="small muted">fees ${money(st.totalFees)}</div></td><td>${pf(st.profitFactor)}</td><td>${pct(st.maxDrawdown)}</td><td>${pct(st.winRate)}<div class="small muted">${st.closedTrades} closed</div></td><td><span class="positive">${money(st.avgWin)}</span> / <span class="negative">${money(st.avgLoss)}</span></td><td>${pauseText(r.pause)}</td></tr>`;}).join('');
 return `<section class="panel section-gap"><div class="panel-head"><div><h2>Scorecard · main vs challengers</h2><p>Net profit after fees and rebates. Challengers trade the same quotes and fees in separate paper accounts; one is promoted only after the daily backtest + live checks.</p></div><span class="status ${main?.state&&main.state!=='normal'?'wait':''}">DRAWDOWN ${esc((main?.state??'normal').toUpperCase())}</span></div>
 <div class="info-box" style="margin:0 16px 12px">${esc(g.label)}: ${eta}.</div>
 ${main?.state==='blocked'?`<div class="info-box" style="margin:0 16px 12px;border-color:var(--red)">Main account is ${pct(main.drawdown)} below its equity peak of ${money(main.peak)}. New entries are blocked until the supervisor or manager sets <code>pause.cleared</code> in data/paper.json. Exits keep running.</div>`:main?.state==='halved'?`<div class="info-box" style="margin:0 16px 12px;border-color:var(--orange)">Main account is ${pct(main.drawdown)} below its equity peak; new position sizes are halved. At 15% new entries stop.</div>`:''}
 <div class="table-wrap"><table><thead><tr><th>ACCOUNT</th><th>EQUITY</th><th>NET AFTER FEES</th><th>PROFIT FACTOR</th><th>MAX DRAWDOWN</th><th>WIN RATE</th><th>AVG WIN / AVG LOSS</th><th>DRAWDOWN PAUSE</th></tr></thead><tbody>${body}</tbody></table></div>
 ${(state.promotionHistory??[]).length?`<div class="body-pad small muted">Latest promotion review ${esc(date(state.promotion?.reviewedAt))}: ${esc(state.promotion?.promoted?`promoted ${state.promotion.promoted}`:'no promotion')}. Multiple-testing penalty uses ${state.promotion?.trials??0} rule sets tried. ${state.promotionHistory.slice(0,(state.challengers??[]).length).map(h=>`${esc(h.challenger)}: ${esc(h.decision)}${h.failed?.length?' ('+esc(h.failed.join(', '))+')':''}`).join(' · ')}</div>`:''}</section>`;
}
function teamPanel(){
 const r=accountMode==='private'?getPrivateState()?.teamReport:accountMode==='shared'?team:null;if(!r?.generatedAt)return '';
 const s=r.allTime,d=r.last24h,pct=Math.max(0,Math.min(1,r.progressToGoal));
 return `<section class="panel section-gap"><div class="panel-head"><div><h2>Team report · goal ${money(r.goal,0)}</h2><p>Manager check ${esc(date(r.generatedAt))}. Paper equity ${money(r.equity)} (${percent(r.returnPct)}), ${(r.progressToGoal*100).toFixed(1)}% of the way from ${money(r.startingEquity,0)}.</p></div><span class="status ${r.verdict==='on-track'?'':'wait'}">${esc(r.verdict.toUpperCase())}</span></div>${r.readiness?`<div class="info-box" style="margin:0 16px 12px;border-color:${r.readiness.ready?'#b9f47a':'var(--orange)'}"><strong>Real Coinbase account: ${r.readiness.ready?'EVIDENCE CHECKS PASSED':'NOT READY'} · ${r.readiness.passed}/${r.readiness.total}</strong><br>${esc(r.readiness.message)}<br>${r.readiness.checks.map(c=>`${c.pass?'✓':'○'} ${esc(c.label)} · <span class="muted">${esc(c.value)}</span>`).join('<br>')}</div>`:''}<div class="body-pad prose"><div style="height:8px;background:var(--line,#2a342b);border-radius:4px;overflow:hidden"><div style="height:8px;width:${(pct*100).toFixed(1)}%;background:#b9f47a"></div></div><br>Last 24h: ${d.closedTrades} closed, ${d.wins} wins, net ${money(d.netPnl)} after ${money(d.grossFees)} fees and ${money(d.rebatesCredited)} rebates. All time: ${s.closedTrades} closed, ${s.wins} wins, net ${money(s.netPnl)}. Losing streak ${r.losingStreak}.<br>${Object.entries(r.agents).map(([k,v])=>`<strong>${esc(k)}</strong> · ${esc(v.role)}${v.healthy===false?' · <span class="negative">stalled</span>':''}`).join('<br>')}${r.issues.length?'<br><br><strong>Needs attention:</strong><br>'+r.issues.map(esc).join('<br>'):''}</div></section>`;
}
function supervisorPanel(){
 const r=supervisor;if(!r?.at)return '';
 const pct=Number.isFinite(r.progressPct)?Math.max(0,Math.min(100,r.progressPct)):0;
 return `<section class="panel section-gap"><div class="panel-head"><div><h2>Supervisor report</h2><p>${esc(date(r.at))} · goal ${money(r.goal??85000,0)}</p></div><span class="status ${r.onTrack?'':'wait'}">${r.onTrack?'ON TRACK':'OFF TRACK'}</span></div><div class="body-pad prose"><strong>${money(r.equity)}</strong> paper equity · ${money(r.remaining)} to go · ${pct.toFixed(1)}% of the way from ${money(r.start,0)}<div style="height:8px;background:var(--line,#2a342b);border-radius:4px;overflow:hidden;margin:8px 0"><div style="height:8px;width:${pct.toFixed(1)}%;background:#b9f47a"></div></div>${esc(r.verdict??'')}<br>Last 24h: ${esc(r.last24h??'—')}<br>Readiness: ${esc(r.readiness??'—')}${(r.fixed??[]).length?'<br>Fixed: '+r.fixed.map(esc).join('; '):''}<br><strong>Next step:</strong> ${esc(r.nextStep??'—')}</div></section>`;
}